query:
CREATE TABLE `creators` (
	`id` int AUTO_INCREMENT NOT NULL,
	`name` varchar(128) NOT NULL,
	`slug` varchar(128) NOT NULL,
	`bio` text,
	`avatarKey` text,
	`avatarUrl` text,
	`bannerKey` text,
	`bannerUrl` text,
	`socialLinks` text,
	`seoTitle` varchar(256),
	`seoDescription` text,
	`albumCount` int NOT NULL DEFAULT 0,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `creators_id` PRIMARY KEY(`id`),
	CONSTRAINT `creators_slug_unique` UNIQUE(`slug`)
);
CREATE TABLE `downloads` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`albumId` int NOT NULL,
	`zipSize` bigint,
	`downloadedAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `downloads_id` PRIMARY KEY(`id`)
);
ALTER TABLE `albums` ADD `creatorId` int;
ALTER TABLE `albums` ADD `zipKey` text;
ALTER TABLE `albums` ADD `zipUrl` text;
ALTER TABLE `albums` ADD `zipSize` bigint;
ALTER TABLE `albums` ADD `zipGeneratedAt` timestamp;
ALTER TABLE `tags` ADD `seoTitle` varchar(256);
ALTER TABLE `tags` ADD `seoDescription` text;
CREATE INDEX `idx_creators_slug` ON `creators` (`slug`);
CREATE INDEX `idx_creators_createdAt` ON `creators` (`createdAt`);
CREATE INDEX `idx_downloads_userId` ON `downloads` (`userId`);
CREATE INDEX `idx_downloads_albumId` ON `downloads` (`albumId`);
CREATE INDEX `idx_downloads_downloadedAt` ON `downloads` (`downloadedAt`);

